{
  "headline": "Labetalol hydrochloride is not on FDA's shortage list; Corvale East has 26.3 days on hand and Corvale General has 21.6 days on hand",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows labetalol hydrochloride is not listed as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 301 tablets of the 100 mg presentation with 11.4 tablets used per day, providing 26.3 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 297 tablets of the 100 mg presentation with 13.8 tablets used per day, providing 21.6 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The current label for the product names Heritage Pharma Labs Inc. d/b/a Avet Pharmaceuticals Labs Inc. (FEI 3005139373) as the registered manufacturing plant.",
      "cites": ["E9"]
    },
    {
      "text": "FDA inspection records for that plant show multiple VAI classifications from 2009 through 2018, with the most recent inspection ending 2018-02-06 and a NAI classification on 2023-09-19.",
      "cites": ["E3", "E4", "E5", "E6", "E7", "E8", "E9"]
    },
    {
      "text": "The top-ranked purchasing option is to buy from Advagen Pharma Ltd., which is not on FDA's shortage list today, though its label names no plant we could place.",
      "cites": ["D4"]
    },
    {
      "text": "Secondary options include Biocon Pharma Inc. and BluePoint Laboratories, both also not on the shortage list and with unplaced plant information.",
      "cites": ["D5", "D6"]
    }
  ]
}
